import{_ as o,o as r,c as e,ai as n}from"./chunks/framework.BI5prboT.js";const a="/assets/agent-1.a_PVcq66.png",s="/assets/agent-2.Cr0x1IXj.png",l="/assets/1-react-model.CVuHJX-T.png",i="/assets/2-plan-and-execute.BUEatkR7.png",g="/assets/4-reflective-agent.DOWwNntZ.png",p="/assets/5-tool-augmented.DESwb0ei.png",u="/assets/6-memory-augmented.CLfG5fYL.png",c="/assets/7-rag-agent.o0ItY_yM.png",h="/assets/3-multi-agent.XTghE6xr.png",d="/assets/8-autonomous-loop.C_fioQvs.png",m="/assets/agent-3.C0GPUWq0.png",A="/assets/agent-4.B20eknnw.png",G=JSON.parse('{"title":"如何设计一个 Agent：八种架构与组合路径","description":"","frontmatter":{},"headers":[],"relativePath":"AI/agent-architecture.md","filePath":"AI/agent-architecture.md"}'),_={name:"AI/agent-architecture.md"};function b(f,t,P,q,R,x){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="如何设计一个-agent-八种架构与组合路径" tabindex="-1">如何设计一个 Agent：八种架构与组合路径 <a class="header-anchor" href="#如何设计一个-agent-八种架构与组合路径" aria-label="Permalink to &quot;如何设计一个 Agent：八种架构与组合路径&quot;">​</a></h1><p>「Agent 是什么」见：<a href="./agent.html">Agent 概念</a>。本文回答另一件事：<strong>上手设计时，面前这八种架构该怎么理解、怎么选、怎么组。</strong></p><p>很多人会把 ReAct、RAG、Multi-Agent 当成互斥选项。更稳妥的看法是：它们是可组合的设计模式——有的管「怎么想」，有的管「能调用什么」，有的管「怎样跑起来」。先建立地图，再谈组合。</p><p><img src="'+a+'" alt=""></p><h2 id="不是八选一-而是三层组合" tabindex="-1">不是八选一，而是三层组合 <a class="header-anchor" href="#不是八选一-而是三层组合" aria-label="Permalink to &quot;不是八选一，而是三层组合&quot;">​</a></h2><p>把八种模式塞进一个运行时，会更清楚：</p><table tabindex="0"><thead><tr><th>层</th><th>回答的问题</th><th>常见模式</th></tr></thead><tbody><tr><td><strong>Decision（决策）</strong></td><td>下一步怎么定？</td><td>ReAct、Plan-and-Execute、Reflection</td></tr><tr><td><strong>Capability（能力）</strong></td><td>任务靠什么能力完成？</td><td>Tools、Memory、RAG</td></tr><tr><td><strong>Runtime（运行）</strong></td><td>协作与持续跑到什么程度？</td><td>Multi-Agent、Autonomous Loop</td></tr><tr><td><strong>Guardrails（护栏）</strong></td><td>边界在哪里？</td><td>权限、预算、终止条件、审计</td></tr></tbody></table><p>公式可以记成：</p><blockquote><p><strong>Practical Agent = Model + Patterns + Guardrails</strong></p><p>实用型智能体 = 模型 + 模式 + 约束机制</p></blockquote><p>起步建议永远是：<strong>先用 ReAct + Tools 跑通最小闭环</strong>，再按业务缺口逐层加复杂度。</p><p><img src="'+s+'" alt=""></p><p>下面按层展开八种模式；读完再看「如何组合成真实产品」。</p><hr><h2 id="decision-决策-系统怎样思考和调整" tabindex="-1">Decision（决策）：系统怎样思考和调整 <a class="header-anchor" href="#decision-决策-系统怎样思考和调整" aria-label="Permalink to &quot;Decision（决策）：系统怎样思考和调整&quot;">​</a></h2><h3 id="_1-react-推理与行动-边做边判断" tabindex="-1">1. ReAct（推理与行动）：边做边判断 <a class="header-anchor" href="#_1-react-推理与行动-边做边判断" aria-label="Permalink to &quot;1. ReAct（推理与行动）：边做边判断&quot;">​</a></h3><p><strong>ReAct</strong>（Reason + Act，推理与行动）是最常见的单 Agent 循环：根据目标与当前状态选一步行动 → 调用工具 → 观察结果 → 再决策，直到完成、触达预算，或请求人工。</p><p><img src="'+l+'" alt=""></p><ul><li><strong>适合</strong>：开放研究、排障、路径事先说不清的动态任务</li><li><strong>风险</strong>：死循环、重复调工具、把错误观察当真继续推演</li><li><strong>一句话</strong>：走一步、看结果、再决定下一步；<strong>停止条件</strong>和状态记录必须写死</li></ul><p>和概念文里的「思考 → 行动 → 观察」是同一套骨架，只是工程上要把 Observation（观察结果）规范化、把 STOP（停止）规则显式化。</p><h3 id="_2-plan-and-execute-规划与执行-先拆解-再执行" tabindex="-1">2. Plan-and-Execute（规划与执行）：先拆解，再执行 <a class="header-anchor" href="#_2-plan-and-execute-规划与执行-先拆解-再执行" aria-label="Permalink to &quot;2. Plan-and-Execute（规划与执行）：先拆解，再执行&quot;">​</a></h3><p>目标一上来就很长、依赖很强时，边想边做容易丢全局。<strong>Plan-and-Execute</strong>（规划与执行分离）先让 Planner（规划器）生成带依赖的任务图与完成条件，再让 Executor（执行器）一次只推进当前节点；走不通则 <strong>BLOCKED → REPLAN</strong>（阻塞 → 重规划）。</p><p><img src="'+i+'" alt=""></p><ul><li><strong>适合</strong>：研报、开发交付、项目规划等长链路任务</li><li><strong>风险</strong>：初版计划脱离现实；环境已变仍机械执行旧图</li><li><strong>一句话</strong>：先画路线，再按依赖推进；走不通就重画</li></ul><p>Planner（规划器）管「怎么拆」，Executor（执行器）管「怎么做」；接口是任务状态与重规划，而不是把一切塞进同一次推理。</p><h3 id="_3-reflective-agent-反思型智能体-用反馈闭环提质量" tabindex="-1">3. Reflective Agent（反思型智能体）：用反馈闭环提质量 <a class="header-anchor" href="#_3-reflective-agent-反思型智能体-用反馈闭环提质量" aria-label="Permalink to &quot;3. Reflective Agent（反思型智能体）：用反馈闭环提质量&quot;">​</a></h3><p><strong>Reflection</strong>（反思）把「生成」和「评价」拆开：先出草稿，再按明确标准（事实、完整、格式、引用等）打分；不达标就把反馈写进下一轮，并保留修订记忆避免重复犯错。必须设 <strong>满分阈值</strong> 与 <strong>最大轮数</strong>。</p><p><img src="'+g+'" alt=""></p><ul><li><strong>适合</strong>：代码审查、报告、方案、文案等「有可定义交付标准」的产物</li><li><strong>风险</strong>：模型自评有共同盲区；无限反思烧钱却不更正</li><li><strong>一句话</strong>：按标准找问题，再把反馈变成下一版的输入</li></ul><p>注意：多想几轮 ≠ Reflection（反思）。关键是有 <strong>rubric（评分尺）</strong> 和可执行的修改指令。</p><hr><h2 id="capability-能力-系统能访问哪些能力" tabindex="-1">Capability（能力）：系统能访问哪些能力 <a class="header-anchor" href="#capability-能力-系统能访问哪些能力" aria-label="Permalink to &quot;Capability（能力）：系统能访问哪些能力&quot;">​</a></h2><h3 id="_4-tool-augmented-工具增强-从会说到会做" tabindex="-1">4. Tool-Augmented（工具增强）：从会说到会做 <a class="header-anchor" href="#_4-tool-augmented-工具增强-从会说到会做" aria-label="Permalink to &quot;4. Tool-Augmented（工具增强）：从会说到会做&quot;">​</a></h3><p>模型负责表达「要调什么、参数是什么」；<strong>Tool Gateway</strong>（工具网关）负责校验、鉴权、路由、重试；工具返回<strong>规范化 Observation</strong>（观察结果：状态 / 数据 / 错误 / 审计）再喂回模型。发送、删除、支付等高副作用操作应走人审。</p><p><img src="'+p+'" alt=""></p><ul><li><strong>适合</strong>：搜索、查数、办公自动化、接企业内部系统</li><li><strong>风险</strong>：参数错误、越权、重复提交、盲信工具返回内容</li><li><strong>一句话</strong>：模型提出行动，受控运行时真正执行</li></ul><p>工程上这层常和 MCP / Function Calling（函数调用）相遇：协议解决「怎么接」，Gateway（网关）解决「接了以后怎么控」。更多见：<a href="./mcp.html">MCP</a>。</p><h3 id="_5-memory-augmented-记忆增强-让状态跨轮次延续" tabindex="-1">5. Memory-Augmented（记忆增强）：让状态跨轮次延续 <a class="header-anchor" href="#_5-memory-augmented-记忆增强-让状态跨轮次延续" aria-label="Permalink to &quot;5. Memory-Augmented（记忆增强）：让状态跨轮次延续&quot;">​</a></h3><p>记忆不是无限聊天记录，而是<strong>选择性写入、整理、召回、遗忘</strong>。当前轮进入有限的 Working Memory（工作记忆）；Memory Manager（记忆管理器）决定沉淀到情景记忆（做过什么）、语义记忆（长期事实）、画像（偏好规则），并受相关性、时效、用户同意、可删除、可追溯等策略约束。</p><p><img src="'+u+'" alt=""></p><ul><li><strong>适合</strong>：长期助手、跨会话项目、个性化服务</li><li><strong>风险</strong>：假记忆、过期信息、隐私泄露、无关历史污染当前决策</li><li><strong>一句话</strong>：记住有价值的经验，也要有能力忘记</li></ul><p>和「知识库 / RAG」的分工：Memory（记忆）偏<strong>用户与任务状态</strong>；RAG 偏<strong>外部可检索知识</strong>。入门见：<a href="./knowledge-base.html">知识库</a>。</p><h3 id="_6-rag-agent-检索增强智能体-主动寻找可验证证据" tabindex="-1">6. RAG Agent（检索增强智能体）：主动寻找可验证证据 <a class="header-anchor" href="#_6-rag-agent-检索增强智能体-主动寻找可验证证据" aria-label="Permalink to &quot;6. RAG Agent（检索增强智能体）：主动寻找可验证证据&quot;">​</a></h3><p><strong>RAG</strong>（Retrieval-Augmented Generation，检索增强生成）。生产级 RAG Agent 很少「检索一次就答」。更常见的是：查询规划与改写 → 多源检索（向量 / Web / SQL·Graph）→ 重排压缩成证据包 → 带引用作答 → <strong>Verifier</strong>（校验器）发现冲突或不足则回到规划再搜。</p><p><img src="'+c+'" alt=""></p><ul><li><strong>适合</strong>：企业知识问答、研究分析、要实时事实的客服</li><li><strong>风险</strong>：召回失误、过期材料污染、引用错配、权限过滤失败</li><li><strong>一句话</strong>：先找到可信依据，再让模型组织答案</li></ul><hr><h2 id="runtime-运行时-系统怎样协作和持续运行" tabindex="-1">Runtime（运行时）：系统怎样协作和持续运行 <a class="header-anchor" href="#runtime-运行时-系统怎样协作和持续运行" aria-label="Permalink to &quot;Runtime（运行时）：系统怎样协作和持续运行&quot;">​</a></h2><h3 id="_7-multi-agent-多智能体-用角色分工放大能力" tabindex="-1">7. Multi-Agent（多智能体）：用角色分工放大能力 <a class="header-anchor" href="#_7-multi-agent-多智能体-用角色分工放大能力" aria-label="Permalink to &quot;7. Multi-Agent（多智能体）：用角色分工放大能力&quot;">​</a></h3><p>多个专业角色共享目标、职责不同；<strong>Supervisor</strong>（主管）负责拆分、分派、汇总，处理冲突与终止；中间产物进 <strong>Shared Workspace</strong>（共享工作区 / 黑板 / 消息总线）。价值来自分工是否有效，不来自 Agent 数量。</p><p><img src="'+h+'" alt=""></p><ul><li><strong>适合</strong>：可并行拆分、或需要多视角互审的复杂任务</li><li><strong>风险</strong>：通信成本高、上下文冲突、重复劳动、Supervisor 成为瓶颈</li><li><strong>一句话</strong>：有效分工，而不是堆角色</li></ul><p>常见误区：任务还没跑通单 Agent，就上多人协作——协调成本会先把收益吃掉。</p><h3 id="_8-autonomous-loop-自主循环-从一次任务到持续目标" tabindex="-1">8. Autonomous Loop（自主循环）：从一次任务到持续目标 <a class="header-anchor" href="#_8-autonomous-loop-自主循环-从一次任务到持续目标" aria-label="Permalink to &quot;8. Autonomous Loop（自主循环）：从一次任务到持续目标&quot;">​</a></h3><p>把高层目标存成持久 <strong>Goal + State</strong>（目标 + 状态），按事件或定时驱动 <strong>Observe → Decide → Act → Evaluate</strong>（观察 → 决策 → 行动 → 评估），直到完成、暂停或升级人工。自主性越高，<strong>Guardrails</strong>（护栏：权限、预算、最大循环、审计、人批）必须越强。</p><p><img src="'+d+'" alt=""></p><ul><li><strong>适合</strong>：持续监控、周期研究、运维响应、长项目推进</li><li><strong>风险</strong>：错误目标被放大、成本失控、未授权副作用、停不下来</li><li><strong>一句话</strong>：自主性越高，停止机制和治理必须越强</li></ul><hr><h2 id="如何组合成真实产品" tabindex="-1">如何组合成真实产品 <a class="header-anchor" href="#如何组合成真实产品" aria-label="Permalink to &quot;如何组合成真实产品&quot;">​</a></h2><p>八种模式讲完，设计问题变成：<strong>按任务复杂度，该叠哪几层？</strong></p><h3 id="安全叠加路径" tabindex="-1">安全叠加路径 <a class="header-anchor" href="#安全叠加路径" aria-label="Permalink to &quot;安全叠加路径&quot;">​</a></h3><p><img src="'+m+'" alt=""></p><p>建议顺序：</p><ol><li>需要对外行动 → <strong>Tools + ReAct</strong>（工具 + 推理行动，最小闭环）</li><li>需要私有/实时事实 → <strong>RAG</strong>（检索增强）；需要跨会话体验 → <strong>Memory</strong>（记忆）</li><li>长链路强依赖 → <strong>Planning</strong>（规划）；交付质量敏感 → <strong>Reflection</strong>（反思）</li><li>真要专业分工或持续运行 → 再上 <strong>Multi-Agent</strong>（多智能体） / <strong>Autonomous Loop</strong>（自主循环）</li></ol><p>每加一层能力，同步加：<strong>评估、成本控制、权限治理</strong>。</p><h3 id="参考流-竞品简报-agent" tabindex="-1">参考流：竞品简报 Agent <a class="header-anchor" href="#参考流-竞品简报-agent" aria-label="Permalink to &quot;参考流：竞品简报 Agent&quot;">​</a></h3><p>真实产品很少只用一种模式。下面是一张「可控工作系统」参考骨架——持续生成竞品简报：</p><p><img src="'+A+'" alt=""></p><p>读法：</p><ul><li><strong>Plan + Supervisor</strong>（规划 + 主管）：管任务图、依赖、角色与预算（Plan-and-Execute + Multi-Agent）</li><li><strong>Researcher / Analyst / Writer</strong>（研究员 / 分析师 / 写手）：各自跑 ReAct，分别挂 Tools / RAG / Memory</li><li><strong>Reflection</strong>（反思）：事实审查、质量评分、不达标打回</li><li><strong>底座</strong>：定时触发、预算、权限、检查点、人工审批、审计（Autonomous Runtime 自主运行时 + Guardrails 护栏）</li></ul><p>成熟 Agent 的标准不是「最自主」，而是：<strong>在明确边界内稳定完成目标</strong>——可组合、可观测、可治理。每条自动化路径都要能被看见、被评估、被停下来。</p><h3 id="设计清单-可直接照着填" tabindex="-1">设计清单（可直接照着填） <a class="header-anchor" href="#设计清单-可直接照着填" aria-label="Permalink to &quot;设计清单（可直接照着填）&quot;">​</a></h3><ol><li><strong>边界</strong>：目标、成功标准、禁止事项、预算与人审点</li><li><strong>最小闭环</strong>：单 Agent + ReAct（推理行动）+ Tool Gateway（工具网关）+ 停止条件</li><li><strong>按缺口加层</strong>：缺知识加 RAG（检索增强），缺连续加 Memory（记忆），链路长加 Plan（规划），质量不稳加 Reflection（反思）</li><li><strong>最后才扩 Runtime（运行时）</strong>：分工不动再 Multi-Agent（多智能体）；要持续跑再 Autonomous Loop（自主循环），并加强治理</li><li><strong>验收</strong>：关键路径有日志、有评估、有熔断</li></ol><p>能力演进的另一条叙述（Prompt → Context → Harness → Loop → Graph）见：<a href="./prompt-to-graph.html">从 Prompt 到 Graph</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>八种架构是<strong>模式库</strong>，不是互斥菜单</li><li>Decision（决策）管思考，Capability（能力）管手脚与知识，Runtime（运行）管协作与持续，Guardrails（护栏）管边界</li><li>设计顺序：<strong>ReAct + Tools（推理行动 + 工具）最小闭环 → 按业务缺口叠加 → 同步加强治理</strong></li><li>产品形态用「目标 + 编排 + 角色循环 + 反思 + 运行时护栏」组装，而不是堆更多模型调用</li></ul><p>概念与 Skill / MCP 分工仍以 <a href="./agent.html">Agent 概念</a> 为准；接外部系统见 <a href="./mcp.html">MCP</a>，知识侧见 <a href="./knowledge-base.html">知识库</a>。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>原视频：<a href="https://www.bilibili.com/video/BV1CrKA6YETu/" target="_blank" rel="noreferrer">AI Agent 8 大主流架构</a></li></ul>',78)])])}const y=o(_,[["render",b]]);export{G as __pageData,y as default};
